test-case.test:
(: FTAnd-q1: Basic syntax :)
declare variable $input-context external;
$input-context/books/book[para contains text "software" ftor "ninja"]/title

(: FTAnd-q2: 'or' instead of 'ftor; 'or "ninja"' selects everything :)
declare variable $input-context external;
$input-context/books/book[para contains text "software" or "ninja"]/title

(: FTOr-q3: Both branches false :)
declare variable $input-context external;
$input-context/books/book[para contains text "dingbat" ftor "numbskull"]/title

(: FTOr-q4: One branch false :)
declare variable $input-context external;
$input-context/books/book[para contains text "software" ftor "numbskull"]/title

(: FTOr-q5: One branch false :)
declare variable $input-context external;
$input-context/books/book[para contains text "numbskull" ftor "software"]/title

(: FTOr-three-q1: Two branches false :)
declare variable $input-context external;
$input-context/books/book[para contains text "numbskull" ftor "software" ftor "dingbat"]/title

(: FTOr-three-q2: Two branches false :)
declare variable $input-context external;
$input-context/books/book[para contains text "numbskull" ftor "dingbat" ftor "software"]/title

(: FTOr-three-q3: Two branches false :)
declare variable $input-context external;
$input-context/books/book[para contains text "software" ftor "numbskull" ftor "dingbat"]/title

(: FTOr-expr3: Empty sequence in ftor :)
declare variable $input-context external;
$input-context/books/book[para contains text {()} ftor "ninja"]/title

(: FTOr-badexpr1: Bad computed expression :)
declare variable $input-context external;
$input-context/books/book[para contains text {(1,2)} ftor "ninja"]/title

(: FTOr-andor: Test and/or precedence :)
declare variable $input-context external;
$input-context/books/book[para contains text "numbskull" ftor "software" ftand "ninja"]/title
